use apex_external_cas_draft_research::preview::{color_shift::{ColorShift,PreparedColors},texture::OpaqueTexture};
use sha2::{Digest,Sha256};use std::{fs,io::Read,time::Instant};
fn read(p:&str)->Result<Vec<u8>,Box<dyn std::error::Error>>{let mut b=Vec::new();fs::File::open(p)?.take(33554433).read_to_end(&mut b)?;if b.len()!=33554432{return Err("expected complete2048x4096RGBA".into())}Ok(b)}
fn main()->Result<(),Box<dyn std::error::Error>>{let args:Vec<_>=std::env::args().collect();if args.len()!=3{return Err("cloth base".into())}let cloth=read(&args[1])?;let base=read(&args[2])?;let t=Instant::now();let palette=PreparedColors::new(&cloth)?;let prep=t.elapsed().as_secs_f64()*1000.;println!("{{\"preparation_ms\":{prep},\"distinct\":{},\"retained_bytes\":{},\"cloth_sha256\":\"{:x}\",\"base_sha256\":\"{:x}\"}}",palette.distinct_colors(),palette.retained_bytes(),Sha256::digest(&cloth),Sha256::digest(&base));for i in 0..24i32{let lanes=[(i*337)%16385-8192,(i*499)%16385-8192,(i*1733)%16385-8192,3277+(i*601)%13108];let bits=lanes.iter().enumerate().fold(0u64,|n,(j,v)|n|u64::from(*v as i16 as u16)<<(j*16));let shift=ColorShift::decode(bits)?;let t=Instant::now();let reference=shift.compose_over(OpaqueTexture::new(2048,4096,&base)?,&cloth)?;let reference_ms=t.elapsed().as_secs_f64()*1000.;let t=Instant::now();let candidate=palette.compose_over(shift,OpaqueTexture::new(2048,4096,&base)?)?;let candidate_ms=t.elapsed().as_secs_f64()*1000.;assert_eq!(reference.view().bytes(),candidate.view().bytes());println!("{{\"case\":{i},\"bits\":{bits},\"bytes\":33554432,\"sha256\":\"{:x}\",\"reference_ms\":{reference_ms},\"candidate_ms\":{candidate_ms}}}",Sha256::digest(candidate.view().bytes()));}Ok(())}
